<?php
require dirname(__DIR__).'/public/database.php';
require dirname(__DIR__).'/public/schema.php';
require dirname(__DIR__).'/public/social-plan.php';
$cfg=appConfig();
if(!str_starts_with($cfg['db_name']??'','itu_test_')||!in_array($cfg['db_host']??'',['127.0.0.1','localhost']))exit(2);
$pdo=appDatabase();appSchema($pdo);$_SESSION=[];$pass=0;
function demand($ok,$msg){if(!$ok)throw new RuntimeException($msg);}
function fails($f){try{$f();}catch(RuntimeException $e){if($e instanceof PDOException)throw $e;return;}throw new RuntimeException('Expected rejection');}
function fixture(){global $pdo;opsExec($pdo,'INSERT INTO users(phone,password,biz_name,biz_category,location) VALUES(?,?,?,?,?)',['svc-'.bin2hex(random_bytes(7)),password_hash('Service-test-only',PASSWORD_DEFAULT),'Test cafe','cafe','Тараз']);return (int)$pdo->lastInsertId();}
function runCase($name,$f){global $pass;$f();$pass++;echo "PASS $name\n";}
function postFixture($uid,$key){global $pdo;$img=imagecreatetruecolor(1080,1350);ob_start();imagejpeg($img,null,75);$raw=ob_get_clean();imagedestroy($img);return socialSave($pdo,$uid,['request_key'=>$key,'title'=>'Test poster','caption'=>'Test only','design'=>['headline'=>'Test poster'],'image'=>'data:image/jpeg;base64,'.base64_encode($raw)]);}
$u=fixture();$other=fixture();$owner=['id'=>$u,'biz_name'=>'Test cafe'];$chat='8881100';
opsSaveSettings($pdo,$u,['bot_mode'=>'free','orders_enabled'=>true]);
opsExec($pdo,'INSERT INTO business_catalog(user_id,item_name,item_price,item_cost,category) VALUES(?,?,?,?,?)',[$u,'Латте',1300,400,'Кофе']);$item=(int)$pdo->lastInsertId();
saveCatalogDetails($pdo,$u,$item,catalogDetails(['availability'=>'available','data_mode'=>'demo','unit'=>'300 мл','aliases'=>'кофе, латте'],'cafe'));
runCase('free greeting and catalog never need model credentials',function()use($pdo,$owner,$chat){$hello=opsBotHandle($pdo,$owner,$chat,'Салам',[]);demand(str_contains($hello,'Сәлеметсіз'),'Kazakh greeting');$reply=opsBotHandle($pdo,$owner,$chat,'Сколько стоит кофе?',[]);demand(str_contains($reply,'1 300,00')&&str_contains($reply,'Пример'),'exact demo price');});
runCase('free service excludes internal and other-tenant knowledge',function()use($pdo,$u,$other,$owner,$chat){opsRecord($pdo,$u,'knowledge',['name'=>'Где находится вход','text'=>'Вход со двора','audience'=>'public']);opsRecord($pdo,$u,'knowledge',['name'=>'Где находится сейф','text'=>'PRIVATE-SECRET','audience'=>'internal']);opsRecord($pdo,$other,'knowledge',['name'=>'Где находится вход','text'=>'FOREIGN-SECRET','audience'=>'public']);demand(str_contains(opsBotHandle($pdo,$owner,$chat,'Где находится вход?',[]),'со двора'),'public FAQ');demand(!str_contains(opsBotHandle($pdo,$owner,$chat,'Где находится сейф?',[]),'SECRET'),'internal excluded');});
runCase('order requires explicit quantity and customer confirmation; duplicate yes cannot create twice',function()use($pdo,$owner,$chat,$u){$text=opsBotHandle($pdo,$owner,$chat,'Заказ: Латте, 2',[]);demand(str_contains($text,'Подтверждаю')&&str_contains($text,'2 600,00'),'quote');demand((int)opsOne($pdo,'SELECT COUNT(*) n FROM ops_orders WHERE user_id=?',[$u])['n']===0,'no premature order');opsBotHandle($pdo,$owner,$chat,'Подтверждаю',[]);opsBotHandle($pdo,$owner,$chat,'Подтверждаю',[]);demand((int)opsOne($pdo,'SELECT COUNT(*) n FROM ops_orders WHERE user_id=?',[$u])['n']===1,'single order');demand((int)opsOne($pdo,'SELECT is_demo FROM ops_orders WHERE user_id=?',[$u])['is_demo']===1,'demo remains demo');});
runCase('handoff creates a real ticket and later messages append',function()use($pdo,$owner,$chat,$u){$r=opsBotHandle($pdo,$owner,$chat,'Нужен сотрудник',[]);demand(str_contains($r,'Создал обращение'),'ticket confirmed');$r=opsBotHandle($pdo,$owner,$chat,'Уточнение вопроса',[]);$tickets=opsRecords($pdo,$u,'ops_ticket');demand(count($tickets)===1&&count($tickets[0]['data']['messages'])===2,'one ticket with followup');opsTicketUpdate($pdo,$u,$tickets[0]['id'],['status'=>'resolved']);demand(str_contains(opsBotHandle($pdo,$owner,$chat,'Здравствуйте',[]),'Здравствуйте'),'bot resumes after resolve');});
runCase('history query works with production collation mismatch',function()use($pdo,$u,$chat){$pdo->exec('SET NAMES utf8 COLLATE utf8_unicode_ci');opsRecord($pdo,$u,'telegram',['chat_id'=>$chat,'text'=>'hello']);$rows=opsAll($pdo,"SELECT payload FROM aulieata_records WHERE user_id=? AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.chat_id')) AS BINARY)=CAST(? AS BINARY)",[$u,$chat]);demand(count($rows)>0,'history query');$pdo->exec('SET NAMES utf8mb4');});
runCase('weekly slots honor chosen day, minute, timezone and busy slots',function(){ $s=['time'=>'12:37','days'=>[1,3,5]];$now=new DateTimeImmutable('2026-10-18 18:00:00+05:00');$slots=socialPlanSlots($s,2,['2026-10-19 07:37:00'],$now);demand($slots===['2026-10-21T12:37','2026-10-23T12:37'],'slots');fails(fn()=>socialPlanClean(['days'=>[]]));fails(fn()=>socialPlanClean(['time'=>'24:00']));fails(fn()=>socialPlanSlots(['time'=>'12:00','days'=>[1]],30,[],$now));});
runCase('schedule preferences are tenant-scoped',function()use($pdo,$u,$other){socialPlanStore($pdo,$u,['time'=>'18:43','days'=>[2,6]]);demand(socialPlanSettings($pdo,$u)['time']==='18:43','saved');demand(socialPlanSettings($pdo,$other)['time']==='12:00','isolated');});
// Mock a verified connection without calling Instagram.
opsExec($pdo,"INSERT INTO aulieata_instagram_connections(user_id,account_id,username,account_type,token_box,check_status,checked_at) VALUES(?,?,?,?,?,?,?)",[$u,'178414'.random_int(100000000,999999999),'service_fixture','BUSINESS',sealToken('test-token',$cfg),'verified',socialNow()]);
$a=postFixture($u,'service-'.bin2hex(random_bytes(10)));$b=postFixture($u,'service-'.bin2hex(random_bytes(10)));
$settings=['time'=>'15:33','days'=>[1,2,3,4,5,6,7]];
$plan=socialPlanPreview($pdo,$u,['ids'=>[$a['id'],$b['id']],'settings'=>$settings]);$apply=$plan+['request_key'=>'plan-'.bin2hex(random_bytes(12)),'approved'=>true];
runCase('batch preview is read-only and stale second post rolls back first',function()use($pdo,$u,$plan,$apply,$a){demand(socialRow($pdo,$u,$a['id'])['status']==='draft','preview only');$bad=$apply;$bad['posts'][1]['version']=99;fails(fn()=>socialPlanApply($pdo,$u,$bad));demand(socialRow($pdo,$u,$a['id'])['status']==='draft','rollback all');});
runCase('batch apply queues once and cross-tenant access is rejected',function()use($pdo,$u,$other,$apply,$a){$r=socialPlanApply($pdo,$u,$apply);demand($r['count']===2,'two queued');$repeat=socialPlanApply($pdo,$u,$apply);demand($repeat['posts'][0]['due_at']===$r['posts'][0]['due_at'],'retry same schedule');fails(fn()=>socialPlanPreview($pdo,$other,['ids'=>[$a['id']],'settings'=>[]]));socialChange($pdo,$u,$a['id'],'cancel');demand(socialRow($pdo,$u,$a['id'])['status']==='draft','cancel works');});
echo "RESULT $pass passed; no external models or messages called.\n";
